return [
  { json: { nome: 'Open WebUI', url: 'https://github.com/open-webui/open-webui/releases.atom' } },
  { json: { nome: 'Ollama', url: 'https://github.com/ollama/ollama/releases.atom' } },
  { json: { nome: 'LiteLLM', url: 'https://github.com/BerriAI/litellm/releases.atom' } }
];

const feeds = $('Lista de projetos').all();
const limite = Date.now() - 8 * 24 * 3600 * 1000;
const limpar = t => String(t || '').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&').replace(/<[^>]+>/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/\s+/g, ' ').trim();
const saida = [];
$input.all().forEach((it, i) => {
  const nome = feeds[i] ? feeds[i].json.nome : 'Projeto ' + (i + 1);
  const entradas = String(it.json.data || '').split('<entry>').slice(1);
  let n = 0;
  entradas.forEach(e => {
    if (n >= 3) return;
    const titulo = ((e.match(/<title>([\s\S]*?)<\/title>/) || [])[1] || '').trim();
    const data = Date.parse(((e.match(/<updated>([\s\S]*?)<\/updated>/) || [])[1] || ''));
    const corpo = limpar(((e.match(/<content[^>]*>([\s\S]*?)<\/content>/) || [])[1] || '')).slice(0, 400);
    if (/nightly|\bdev\b|\brc\d*\b|alpha|beta/i.test(titulo)) return;
    if (!isNaN(data) && data >= limite) { saida.push('- ' + nome + ' ' + titulo + ': ' + corpo); n++; }
  });
});
if (saida.length === 0) return [];
return [{ json: { prompt: saida.join('\n') } }];
